-- Oracle starter DDL. Validate and test in the target Oracle version.
CREATE TABLE season (season_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, season_code CHAR(1) NOT NULL CHECK (season_code IN ('A','B','C')), agricultural_year VARCHAR2(20) NOT NULL, source_filename VARCHAR2(255), CONSTRAINT uq_season UNIQUE(season_code, agricultural_year));
CREATE TABLE geographic_area (area_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, province VARCHAR2(100) NOT NULL, district VARCHAR2(100) NOT NULL, CONSTRAINT uq_area UNIQUE(province,district));
CREATE TABLE stratum (stratum_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, stratum_name VARCHAR2(150) NOT NULL UNIQUE);
CREATE TABLE farm_type (farm_type_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, source_value VARCHAR2(100) NOT NULL UNIQUE);
CREATE TABLE crop_category (category_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, category_name VARCHAR2(100) NOT NULL UNIQUE);
CREATE TABLE crop (crop_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, crop_name VARCHAR2(150) NOT NULL UNIQUE, category_id NUMBER REFERENCES crop_category(category_id));
CREATE TABLE farm_unit (farm_unit_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, season_id NUMBER NOT NULL REFERENCES season(season_id), segment_id VARCHAR2(100) NOT NULL, farmer_source_id VARCHAR2(100) NOT NULL, area_id NUMBER NOT NULL REFERENCES geographic_area(area_id), stratum_id NUMBER REFERENCES stratum(stratum_id), farm_type_id NUMBER REFERENCES farm_type(farm_type_id), gender VARCHAR2(30), age_years NUMBER(3), CONSTRAINT uq_farm_unit UNIQUE(season_id,segment_id,farmer_source_id), CONSTRAINT ck_farm_age CHECK(age_years IS NULL OR age_years BETWEEN 0 AND 120));
CREATE TABLE plot (plot_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, farm_unit_id NUMBER NOT NULL REFERENCES farm_unit(farm_unit_id), plot_number VARCHAR2(50) NOT NULL, plot_area_m2 NUMBER(18,3), plot_weight NUMBER(18,8), CONSTRAINT uq_plot UNIQUE(farm_unit_id,plot_number), CONSTRAINT ck_plot_area CHECK(plot_area_m2 IS NULL OR plot_area_m2 >= 0), CONSTRAINT ck_plot_weight CHECK(plot_weight IS NULL OR plot_weight >= 0));
CREATE TABLE production_record (production_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, farm_unit_id NUMBER NOT NULL REFERENCES farm_unit(farm_unit_id), crop_id NUMBER NOT NULL REFERENCES crop(crop_id), total_crop_harvest_kg NUMBER(20,3), utilization_reported_loss_kg NUMBER(20,3), source_row_key VARCHAR2(200), CONSTRAINT uq_prod_farm_crop UNIQUE(farm_unit_id,crop_id), CONSTRAINT ck_crop_harvest CHECK(total_crop_harvest_kg IS NULL OR total_crop_harvest_kg >= 0));
CREATE TABLE plot_crop (plot_crop_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, plot_id NUMBER NOT NULL REFERENCES plot(plot_id), crop_id NUMBER NOT NULL REFERENCES crop(crop_id), plot_harvest_kg NUMBER(20,3), CONSTRAINT uq_plot_crop UNIQUE(plot_id,crop_id), CONSTRAINT ck_plot_harvest CHECK(plot_harvest_kg IS NULL OR plot_harvest_kg >= 0));
CREATE TABLE use_type (use_code VARCHAR2(30) PRIMARY KEY, use_label VARCHAR2(120) NOT NULL, source_question VARCHAR2(30));
CREATE TABLE utilization (production_id NUMBER NOT NULL REFERENCES production_record(production_id), use_code VARCHAR2(30) NOT NULL REFERENCES use_type(use_code), quantity_kg NUMBER(20,3), PRIMARY KEY(production_id,use_code), CONSTRAINT ck_util_qty CHECK(quantity_kg IS NULL OR quantity_kg >= 0));
CREATE TABLE loss_type (loss_code VARCHAR2(30) PRIMARY KEY, loss_label VARCHAR2(120) NOT NULL, source_question VARCHAR2(30) NOT NULL, loss_stage VARCHAR2(12) NOT NULL CHECK(loss_stage IN ('PRE','POST')));
CREATE TABLE loss_record (production_id NUMBER NOT NULL REFERENCES production_record(production_id), loss_code VARCHAR2(30) NOT NULL REFERENCES loss_type(loss_code), quantity_kg NUMBER(20,3), PRIMARY KEY(production_id,loss_code));
CREATE TABLE import_batch (batch_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, source_filename VARCHAR2(255) NOT NULL, season_code CHAR(1) CHECK(season_code IN ('A','B','C')), started_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, completed_at TIMESTAMP, rows_read NUMBER DEFAULT 0 NOT NULL, rows_loaded NUMBER DEFAULT 0 NOT NULL, rows_rejected NUMBER DEFAULT 0 NOT NULL, batch_status VARCHAR2(20) DEFAULT 'STARTED');
CREATE TABLE import_reject (reject_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, batch_id NUMBER NOT NULL REFERENCES import_batch(batch_id), source_row_number NUMBER, reject_reason VARCHAR2(1000) NOT NULL, raw_payload CLOB, rejected_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL);
CREATE INDEX ix_farm_unit_area ON farm_unit(area_id);
CREATE INDEX ix_farm_unit_season ON farm_unit(season_id);
CREATE INDEX ix_production_crop ON production_record(crop_id);
CREATE INDEX ix_plot_farm_unit ON plot(farm_unit_id);
CREATE INDEX ix_loss_record_code ON loss_record(loss_code);